import {locales} from './locales.js';
import {holidays,weekend,count,shift} from './core.js';
const lang=document.documentElement.lang,T=locales[lang]||locales.ko,$=id=>document.getElementById(id);
document.title=T.title;
document.querySelectorAll('[data-t]').forEach(el=>el.textContent=T[el.dataset.t]);
const names={ko:'한국어',en:'English',es:'Español',zh:'简体中文',ja:'日本語',de:'Deutsch'};
for(const [code,name]of Object.entries(names)){let o=new Option(name,code);o.selected=code===lang;$('language').add(o);}
$('language').addEventListener('change',()=>location.href=new URL($('language').value==='ko'?'./':$('language').value+'/',document.baseURI));
T.weekdays.forEach((name,i)=>{let l=document.createElement('label'),c=document.createElement('input');c.type='checkbox';c.value=i;c.name='weekend';c.checked=i===0||i===6;l.append(c,document.createTextNode(name));$('weekends').append(l);});
let lastRows=[],lastText='';
function rules(){return [weekend([...document.querySelectorAll('[name=weekend]:checked')].map(e=>e.value)),holidays($('holidays').value)];}
function clear(){lastRows=[];lastText='';$('error').textContent='';$('result').replaceChildren();$('download').disabled=true;$('copy').disabled=true;$('status').textContent=T.updated;}
function fail(e){$('error').textContent=T.errors[e.message]||T.errors.date;}
function metric(value,label){let d=document.createElement('div'),n=document.createElement('div'),p=document.createElement('p');n.className='metric';n.textContent=value;p.textContent=label;d.append(n,p);return d;}
$('calculate').onclick=()=>{clear();try{const [w,h]=rules(),r=count($('start').value,$('end').value,w,h,$('includeStart').checked,$('includeEnd').checked);lastRows=r.rows;let stats=document.createElement('div');stats.className='stats';for(let key of ['work','weekend','holiday'])stats.append(metric(r.totals[key],T[key]));$('result').append(stats);let total=document.createElement('p');total.textContent=T.total+': '+r.rows.length;$('result').append(total);let wrap=document.createElement('div');wrap.className='tablewrap';let table=document.createElement('table'),head=document.createElement('thead'),hr=document.createElement('tr');[T.date,T.day,T.status].forEach(s=>{let th=document.createElement('th');th.scope='col';th.textContent=s;hr.append(th);});head.append(hr);let body=document.createElement('tbody');for(let r of lastRows.slice(0,500)){let tr=document.createElement('tr');[r.date,T.weekdays[r.day],T[r.status]].forEach(s=>{let td=document.createElement('td');td.textContent=s;tr.append(td);});tr.className=r.status;body.append(tr);}table.append(head,body);wrap.append(table);$('result').append(wrap);lastText=[T.result,$('start').value+' → '+$('end').value,...['work','weekend','holiday'].map(k=>T[k]+': '+r.totals[k])].join('\n');$('download').disabled=false;$('copy').disabled=false;$('status').textContent=lastRows.length>500?'500 / '+lastRows.length:T.total+': '+lastRows.length;}catch(e){fail(e);}};
$('shift').onclick=()=>{clear();try{let [w,h]=rules(),date=shift($('base').value,$('amount').value,w,h);$('result').append(metric(date,T.result));lastText=T.result+': '+date;$('copy').disabled=false;$('status').textContent='';}catch(e){fail(e);}};
$('download').onclick=()=>{const quote=s=>'"'+String(s).replaceAll('"','""')+'"';let text=[[T.date,T.day,T.status],...lastRows.map(r=>[r.date,T.weekdays[r.day],T[r.status]])].map(r=>r.map(quote).join(',')).join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\uFEFF'+text],{type:'text/csv;charset=utf-8'}));a.download='workdays.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
$('copy').onclick=async()=>{try{await navigator.clipboard.writeText(lastText);$('status').textContent=T.copied;}catch{$('status').textContent=T.copyFail;}};
function sample(){$('start').value='2026-10-26';$('end').value='2026-11-06';$('base').value='2026-10-26';$('amount').value='10';$('holidays').value='2026-11-03';$('includeStart').checked=true;$('includeEnd').checked=true;document.querySelectorAll('[name=weekend]').forEach(c=>c.checked=['0','6'].includes(c.value));$('calculate').click();}
$('sample').onclick=sample;document.querySelectorAll('input,textarea').forEach(e=>e.addEventListener('input',clear));sample();
